examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchUsageMeter(
        items = listOf(
            MonarchUsageMeterItem({{items.0.label}}, used = {{items.0.used|double}}, id = {{items.0.id}}, limit = {{items.0.limit|double}}),
            MonarchUsageMeterItem({{items.1.label}}, used = {{items.1.used|double}}, id = {{items.1.id}}, limit = {{items.1.limit|double}}),
            MonarchUsageMeterItem({{items.2.label}}, used = {{items.2.used|double}}, id = {{items.2.id}}, limit = {{items.2.limit|double}}, unit = {{items.2.unit}}),
            MonarchUsageMeterItem({{items.3.label}}, used = {{items.3.used|double}}, id = {{items.3.id}}, description = {{items.3.description}}),
        ),
        title = {{title}},
        period = {{period}},
        resetsAtMillis = {{resetsAt|millis}},
        timeZone = {{timeZone}},
        statusIcon = { over ->
            MonarchIcon(
                if (over) SampleIcons.Error else SampleIcons.Warning,
                contentDescription = null,
                size = MonarchIconSize.Sm,
            )
        },
    )
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

